/**
 * @description One outbound callout through the connection's Named Credential, and what its reply means for the
 * transaction: Success or Sent, or Failed. A temporary failure is planned for auto-retry when the event allows it,
 * otherwise it says it can be retried by hand. An Apex Auth connection's Auth Class adds the login before the send; a
 * 401 then logs in again and resends once.
 * @group Integration Hub
 */
public with sharing class IntegrationHubCallout {

    private static final Integer BODY_MAX = 131072;
    private static final Set<Integer> RETRY_CODES = new Set<Integer>{ 408, 429 };
    /** @description Outcome of a 2xx reply. */
    @TestVisible
    private static final String OUTCOME_OK = 'ok';
    /** @description Outcome of a reply worth retrying (408, 429, 5xx). */
    @TestVisible
    private static final String OUTCOME_TEMPORARY = 'temporary';
    /** @description Outcome of any other reply. */
    @TestVisible
    private static final String OUTCOME_PERMANENT = 'permanent';

    /**
     * @description A transaction with its event, connection and reply.
     */
    public class Delivery {
        /** @description The transaction. */
        public IH_Transaction__c txn;
        /** @description Its event. */
        public IH_Event__c ev;
        /** @description The event's connection. */
        public IH_Connection__c conn;
        /** @description The reply, when the call was made. */
        public HttpResponse res;
        /** @description The full body to send; can be longer than what Request_Payload__c stores. */
        public String body;
        /** @description True once the callout was tried; each try is logged as an Integration Attempt. */
        public Boolean attempted = false;
        /** @description New when the payload was built for this send, Original when the stored one was sent. */
        public String payloadUsed = 'Original';

        /**
         * @description A delivery of a transaction.
         * @param t the transaction
         * @param e its event
         */
        public Delivery(IH_Transaction__c t, IH_Event__c e) {
            txn = t;
            ev = e;
        }

        /**
         * @description Callout timeout in milliseconds.
         * @return the timeout
         */
        public Integer timeoutMs() {
            return conn == null || conn.Timeout_Seconds__c == null ? 60000 : conn.Timeout_Seconds__c.intValue() * 1000;
        }
    }

    /**
     * @description Everything a request is built from, without records.
     */
    public class RequestSpec {
        /** @description Named Credential API name. */
        public String namedCredential;
        /** @description Event path, may hold {recordId} and {transactionId}. */
        public String path;
        /** @description HTTP method; POST when blank. */
        public String method;
        /** @description Timeout in milliseconds. */
        public Integer timeoutMs;
        /** @description Extra headers as a JSON object, or blank. */
        public String headersJson;
        /** @description Correlation Id header value. */
        public String correlationId;
        /** @description Related record Id for the path. */
        public String recordId;
        /** @description Transaction Id for the path. */
        public String transactionId;
        /** @description Body to send; empty when null. */
        public String body;
    }

    /**
     * @description Makes the callout and applies the outcome to the transaction (no DML). An Apex Auth connection runs
     * its Auth Class first; a class that is missing or fails with its own error fails the transaction (permanent), a
     * callout error or timeout at its token URL is a temporary failure (auto-retry applies). After a 401 an Apex
     * Auth send logs in again (refresh) and is resent once, when the callout limit allows it.
     * @param d the delivery
     */
    public static void deliver(Delivery d) {
        IH_Transaction__c t = d.txn;
        t.Next_Retry_At__c = null;
        String problem = setupProblem(d);
        if (problem != null) {
            IntegrationHubOutcome.failPermanent(t, problem);
            return;
        }
        t.Target_Name__c = d.conn.Name;
        t.Last_Attempt__c = System.now();
        t.Retry_Count__c = (t.Retry_Count__c == null ? 0 : t.Retry_Count__c) + 1;
        d.attempted = true;
        try {
            d.res = IntegrationHubConnectionAuth.sendThrough(request(d), d.conn, d.ev.Event_Key__c);
        } catch (IntegrationHubConnectionAuth.LoginUnavailableException e) {
            IntegrationHubOutcome.failTransient(t, d.ev, e.getMessage());
            return;
        } catch (IntegrationHubConnectionAuth.LoginException e) {
            IntegrationHubOutcome.failPermanent(t, e.getMessage());
            return;
        } catch (Exception e) {
            IntegrationHubOutcome.failTransient(t, d.ev, 'Callout failed: ' + e.getMessage());
            return;
        }
        applyReply(d);
    }

    private static String setupProblem(Delivery d) {
        if (d.ev == null || d.ev.Active__c != true) {
            return 'The event is missing or inactive.';
        }
        if (d.conn == null || d.conn.Active__c != true || String.isBlank(d.conn.Named_Credential__c)) {
            return 'The connection is missing, inactive or has no Named Credential.';
        }
        if (!validHeaders(d.conn.Headers__c)) {
            return 'Connection headers must be a JSON object.';
        }
        return null;
    }

    /**
     * @description Whether connection headers are blank or a JSON object.
     * @param headersJson the headers text
     * @return true when usable
     */
    @TestVisible
    private static Boolean validHeaders(String headersJson) {
        return String.isBlank(headersJson) || parseObject(headersJson) instanceof Map<String, Object>;
    }

    private static HttpRequest request(Delivery d) {
        RequestSpec spec = new RequestSpec();
        spec.namedCredential = d.conn.Named_Credential__c;
        spec.path = d.ev.Path__c;
        spec.method = d.ev.Http_Method__c;
        spec.timeoutMs = d.timeoutMs();
        spec.headersJson = d.conn.Headers__c;
        spec.correlationId = String.isBlank(d.txn.Correlation_Id__c) ? String.valueOf(d.txn.Id) : d.txn.Correlation_Id__c;
        spec.recordId = d.txn.Related_Record_Id__c;
        spec.transactionId = String.valueOf(d.txn.Id);
        spec.body = d.body != null ? d.body : d.txn.Request_Payload__c;
        HttpRequest req = buildRequest(spec);
        d.txn.Request_Url__c = IntegrationHub.clip(req.getMethod() + ' ' + req.getEndpoint(), 255);
        return req;
    }

    /**
     * @description Builds the HTTP request from plain values: endpoint is the Named Credential plus the path, the
     * method defaults to POST, the connection headers are merged over the defaults. The payload preview uses it too.
     * @param spec the request values
     * @return the request
     */
    public static HttpRequest buildRequest(RequestSpec spec) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:' + spec.namedCredential + IntegrationHubRequestParts.resolvePath(spec.path, spec.recordId, spec.transactionId));
        req.setMethod(String.isBlank(spec.method) ? 'POST' : spec.method);
        req.setTimeout(spec.timeoutMs);
        IntegrationHubRequestParts.addHeaders(req, spec.correlationId, spec.headersJson);
        req.setBody(IntegrationHubRequestParts.orEmpty(spec.body));
        return req;
    }


    private static void applyReply(Delivery d) {
        IH_Transaction__c t = d.txn;
        Integer code = d.res.getStatusCode();
        t.Http_Status_Code__c = code;
        t.Response_Body__c = IntegrationHub.clip(d.res.getBody(), BODY_MAX);
        String outcome = outcomeFor(code);
        if (outcome == OUTCOME_OK) {
            t.Status__c = successStatus(d.ev);
            t.Completed_At__c = t.Status__c == IntegrationHub.STATUS_SUCCESS ? System.now() : null;
            t.Error_Message__c = null;
            t.Error_Summary__c = null;
            t.External_Reference_Id__c = reference(d.res.getBody(), t.External_Reference_Id__c);
        } else if (outcome == OUTCOME_TEMPORARY) {
            IntegrationHubOutcome.failTransient(t, d.ev, 'HTTP ' + code + ': ' + d.res.getBody());
        } else {
            IntegrationHubOutcome.failPermanent(t, 'HTTP ' + code + ': ' + d.res.getBody());
        }
    }

    /**
     * @description What an HTTP status code means: ok (2xx), temporary (408, 429, 5xx) or permanent (anything else).
     * @param code the status code
     * @return OUTCOME_OK, OUTCOME_TEMPORARY or OUTCOME_PERMANENT
     */
    @TestVisible
    private static String outcomeFor(Integer code) {
        if (code >= 200 && code < 300) {
            return OUTCOME_OK;
        }
        return RETRY_CODES.contains(code) || code >= 500 ? OUTCOME_TEMPORARY : OUTCOME_PERMANENT;
    }

    /**
     * @description Status after a 2xx reply: Sent when the event expects a callback, otherwise Success.
     * @param ev the event (only Expects_Callback__c is read)
     * @return the status
     */
    @TestVisible
    private static String successStatus(IH_Event__c ev) {
        return ev != null && ev.Expects_Callback__c == true ? IntegrationHub.STATUS_SENT : IntegrationHub.STATUS_SUCCESS;
    }

    /**
     * @description The reference ('reference', else 'id') from a JSON reply, or the current value.
     * @param body the reply body
     * @param current the current reference
     * @return the reference
     */
    @TestVisible
    private static String reference(String body, String current) {
        Object parsed = parseObject(body);
        if (!(parsed instanceof Map<String, Object>)) {
            return current;
        }
        Map<String, Object> reply = (Map<String, Object>) parsed;
        Object ref = reply.get('reference') != null ? reply.get('reference') : reply.get('id');
        return ref == null ? current : IntegrationHub.clip(String.valueOf(ref), 255);
    }

    /**
     * @description Parses JSON text, or null when blank or invalid.
     * @param text the text
     * @return the parsed value, or null
     */
    @TestVisible
    private static Object parseObject(String text) {
        try {
            return String.isBlank(text) ? null : JSON.deserializeUntyped(text);
        } catch (JSONException e) {
            return null;
        }
    }

}
